fn torneo(valores: &Vec<i32>, i: usize, j: usize, k: usize) -> (usize, usize) {
    // Extract the three values
    let vi = valores[i];
    let vj = valores[j];
    let vk = valores[k];

    // Build a small array of (index, value) pairs and sort it descending by value.
    let mut triplet = [(i, vi), (j, vj), (k, vk)];
    triplet.sort_by(|a, b| b.1.cmp(&a.1)); // Sort so the largest value is first

    // Return the indices of the top two values in non‐increasing order
    (triplet[0].0, triplet[1].0)
}

